
package com.curso.formagest.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import lombok.Getter;
import lombok.Setter;
import lombok.NoArgsConstructor;

/**
 * Represents a student registered in FormaGest.
 *
 * Maps to the "alumno" table in PostgreSQL.
 * Includes validation rules for student information.
 */
@Entity
@Table(name = "alumno")
@Getter
@Setter
@NoArgsConstructor
public class Alumno {

    /**
     * Unique identifier generated by PostgreSQL.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Student's first name.
     * Required and limited to 80 characters.
     */
    @NotBlank(message = "El nombre es obligatorio")
    @Size(max = 80, message = "El nombre no puede superar 80 caracteres")
    @Column(nullable = false, length = 80)
    private String nombre;

    /**
     * Student's last name or surnames.
     * Required and limited to 120 characters.
     */
    @NotBlank(message = "Los apellidos son obligatorios")
    @Size(max = 120, message = "Los apellidos no pueden superar 120 caracteres")
    @Column(nullable = false, length = 120)
    private String apellidos;

    /**
     * Unique email address of the student.
     * Required, correctly formatted and limited to 150 characters.
     */
    @NotBlank(message = "El email es obligatorio")
    @Email(message = "El formato del email no es válido")
    @Size(max = 150, message = "El email no puede superar 150 caracteres")
    @Column(nullable = false, unique = true, length = 150)
    private String email;

    /**
     * Optional contact phone number.
     * Limited to 20 characters.
     */
    @Size(max = 20, message = "El teléfono no puede superar 20 caracteres")
    @Column(length = 20)
    private String telefono;
}
